/**
 * WorkloadReport Component
 * Displays workload distribution and capacity metrics
 */

import React from 'react';
import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import type { WorkloadMetrics } from '../../../models/Report';
import styles from './WorkloadReport.module.css';

ChartJS.register(ArcElement, Tooltip, Legend);

interface WorkloadReportProps {
  data: WorkloadMetrics;
}

export const WorkloadReport: React.FC<WorkloadReportProps> = ({ data }) => {
  const capacityChartData = {
    labels: ['Utilized', 'Available'],
    datasets: [
      {
        data: [data.capacityUtilization.utilized, data.capacityUtilization.available],
        backgroundColor: ['#2563eb', '#e5e7eb'],
      },
    ],
  };

  const capacityChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false,
      },
    },
  };

  return (
    <div className={styles.container}>
      <div className={styles.cardsGrid}>
        {/* Current Workload */}
        <div className={styles.reportCard}>
          <div className={styles.cardHeader}>
            <h3 className={styles.cardTitle}>
              <i className="fas fa-briefcase"></i>
              Current Workload
            </h3>
          </div>
          <div className={styles.cardBody}>
            <div className={styles.workloadList}>
              {data.currentWorkload.map((item) => (
                <div key={item.userId} className={styles.workloadItem}>
                  <div className={styles.userInfo}>
                    <div className={styles.avatar}>{item.avatar}</div>
                    <span className={styles.userName}>{item.userName}</span>
                  </div>
                  <span className={styles.taskCount}>{item.activeTasksCount}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Capacity Utilization */}
        <div className={styles.reportCard}>
          <div className={styles.cardHeader}>
            <h3 className={styles.cardTitle}>
              <i className="fas fa-tachometer-alt"></i>
              Capacity Utilization
            </h3>
          </div>
          <div className={styles.cardBody}>
            <div className={styles.chartContainer}>
              <Doughnut data={capacityChartData} options={capacityChartOptions} />
            </div>
          </div>
        </div>

        {/* Backlog Analysis */}
        <div className={styles.reportCard}>
          <div className={styles.cardHeader}>
            <h3 className={styles.cardTitle}>
              <i className="fas fa-layer-group"></i>
              Backlog Analysis
            </h3>
          </div>
          <div className={styles.cardBody}>
            <div className={styles.backlogContainer}>
              <div className={styles.totalBacklog}>
                <div className={styles.totalValue}>{data.backlog.total}</div>
                <div className={styles.totalLabel}>Tổng backlog items</div>
              </div>
              <div className={styles.divider}></div>
              <div className={styles.backlogBreakdown}>
                <div className={styles.backlogItem}>
                  <div className={`${styles.backlogValue} ${styles.critical}`}>
                    {data.backlog.critical}
                  </div>
                  <div className={styles.backlogLabel}>Critical</div>
                </div>
                <div className={styles.backlogItem}>
                  <div className={`${styles.backlogValue} ${styles.high}`}>
                    {data.backlog.high}
                  </div>
                  <div className={styles.backlogLabel}>High</div>
                </div>
                <div className={styles.backlogItem}>
                  <div className={`${styles.backlogValue} ${styles.medium}`}>
                    {data.backlog.medium}
                  </div>
                  <div className={styles.backlogLabel}>Medium</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
