import React from 'react';
import { format } from 'date-fns';
import { Task } from '../../../../models/Task';
import { getInitials } from '../../utils/formatters';
import styles from './CollaboratorsCard.module.css';

interface CollaboratorsCardProps {
  task: Task;
}

const ROLE_LABELS: Record<string, string> = {
  support:     'Hỗ trợ',
  reviewer:    'Kiểm duyệt',
  contributor: 'Cộng tác',
};

const ROLE_COLORS: Record<string, string> = {
  support:     'var(--purple-500, #8b5cf6)',
  reviewer:    'var(--blue-500, #3b82f6)',
  contributor: 'var(--green-500, #22c55e)',
};

const formatDate = (date: string) => {
  try {
    return format(new Date(date), 'dd/MM/yyyy HH:mm');
  } catch {
    return date;
  }
};

export const CollaboratorsCard: React.FC<CollaboratorsCardProps> = ({ task }) => {
  const activeCollaborators = (task.collaborators ?? []).filter((c) => c.status === 'active');

  if (activeCollaborators.length === 0) return null;

  return (
    <div className={styles.card}>
      <div className={styles.cardHeader}>
        <h3 className={styles.cardTitle}>
          <i className="fas fa-hands-helping"></i>
          Người Hỗ Trợ ({activeCollaborators.length})
        </h3>
      </div>
      <div className={styles.cardBody}>
        {activeCollaborators.map((c) => (
          <div key={c.id} className={styles.collaboratorItem}>
            <div
              className={styles.avatar}
              style={{ backgroundColor: ROLE_COLORS[c.role] ?? 'var(--purple-500, #8b5cf6)' }}
            >
              {getInitials(c.userName)}
            </div>
            <div className={styles.info}>
              <div className={styles.name}>{c.userName}</div>
              <div className={styles.meta}>
                <span className={styles.roleBadge} style={{ color: ROLE_COLORS[c.role] }}>
                  {ROLE_LABELS[c.role] ?? c.role}
                </span>
                {c.effortPercentage > 0 && (
                  <span className={styles.effort}>{c.effortPercentage}%</span>
                )}
              </div>
              <div className={styles.assignedBy}>
                Giao bởi {c.assignedByName ?? 'N/A'} · {formatDate(c.assignedAt)}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};
