import React from 'react';
import { SLABadge } from '../../../../components/common/SLABadge';
import { formatSLATime } from '../../utils/formatters';
import styles from './SLACard.module.css';

interface SLACardProps {
  slaRemaining?: number;
  status: 'safe' | 'warning' | 'danger';
}

export const SLACard: React.FC<SLACardProps> = ({ slaRemaining, status }) => {
  return (
    <div className={styles.slaCard}>
      <div className={styles.cardHeader}>
        <h3 className={styles.cardTitle}>Trạng thái SLA</h3>
      </div>
      <div className={styles.cardBody}>
        <div className={styles.timeDisplay}>
          {formatSLATime(slaRemaining)}
        </div>
        <div className={styles.timeLabel}>Thời gian còn lại</div>
        <div className={styles.slaBadge}>
          <SLABadge status={status} timeRemaining={formatSLATime(slaRemaining)} />
        </div>
      </div>
    </div>
  );
};
