import React, { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { requestHelp } from '../../../store/slices/ticketsSlice';
import { addToast } from '../../../store/slices/uiSlice';
import { UUID } from '../../../models/common';
import { Slideout } from '../../common/Slideout';
import { TextArea } from '../../common/TextArea';
import styles from './RequestHelpModal.module.css';

export interface RequestHelpModalProps {
  isOpen: boolean;
  ticketId: UUID;
  onClose: () => void;
  onSuccess?: () => void;
}

export const RequestHelpModal: React.FC<RequestHelpModalProps> = ({
  isOpen,
  ticketId,
  onClose,
  onSuccess,
}) => {
  const dispatch = useAppDispatch();
  const ticket   = useAppSelector((s) => s.tickets.selectedTicket);
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen) setDescription('');
  }, [isOpen]);

  const handleSubmit = async () => {
    if (!description.trim()) {
      dispatch(addToast({ message: 'Vui lòng mô tả nội dung cần hỗ trợ', type: 'error' }));
      return;
    }
    setLoading(true);
    try {
      await dispatch(requestHelp({ ticketId, description: description.trim() })).unwrap();
      dispatch(addToast({ message: 'Yêu cầu hỗ trợ đã được gửi thành công', type: 'success' }));
      onClose();
      onSuccess?.();
    } catch (err: any) {
      dispatch(addToast({ message: err?.message || 'Không thể gửi yêu cầu hỗ trợ', type: 'error' }));
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setDescription('');
    onClose();
  };

  return (
    <Slideout
      isOpen={isOpen}
      onClose={handleCancel}
      title="Yêu Cầu Hỗ Trợ"
      width="520px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleCancel,
        leftDisabled: loading,
        rightLabel: loading ? 'Đang gửi...' : 'Gửi yêu cầu hỗ trợ',
        rightAction: handleSubmit,
        rightDisabled: loading,
      }}
    >
      <div className={styles.form}>
        {ticket && (
          <div className={styles.summary}>
            <p className={styles.summaryLabel}>Phiếu yêu cầu</p>
            <p className={styles.summaryTitle}>{ticket.title}</p>
          </div>
        )}

        <div className={styles.field}>
          <label className={styles.label}>
            Nội dung cần hỗ trợ <span className={styles.required}>*</span>
          </label>
          <TextArea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Mô tả chi tiết vấn đề bạn cần được hỗ trợ..."
            rows={5}
            disabled={loading}
          />
          <span className={styles.hint}>Bắt buộc — mô tả rõ nội dung và lý do cần hỗ trợ.</span>
        </div>
      </div>
    </Slideout>
  );
};
